                    return None

                # Get the target
                target = links[canonical]

                # Remove the symlink from result
                result.pop()

                # Make target absolute if needed
                if not target.startswith('/'):
                    # Target is relative to directory containing the link
                    if len(result) == 0:
                        link_dir = '/'
                    else:
                        link_dir = '/' + '/'.join(result)

                    if link_dir == '/':
                        target = '/' + target
                    else:
                        target = link_dir + '/' + target

                # Recursively resolve the target
                resolved_target = resolve_internal(target)
                if resolved_target is None:
                    return None

                # Parse resolved target back to components
                target_parts = resolved_target.split('/')
                if target_parts[0] == '':
                    target_parts = target_parts[1:]

                result = target_parts[:-1] if len(target_parts) > 0 else []

        # Build final path
        if len(result) == 0:
            return '/'
        return '/' + '/'.join(result)

    # Convert relative path to absolute
    if not path.startswith('/'):
        if cwd == '/':
            absolute_path = '/' + path
        else:
            absolute_path = cwd + '/' + path
    else:
        absolute_path = path

    return resolve_internal(absolute_path)
